'use strict';
const Labels={async form(){const m=await Business.load();Flow.form('捆包二维码标签',`<p>二维码仅含稳定UUID，不含重量、客户或权限。编号可多行，也可按批次/入库单筛选；最多200捆。</p><label>捆包编号（每行一捆）<textarea name="numbers" rows="4"></textarea></label><label>生产批次（可选）<select name="batch_id">${Business.options(m.batches,null,'code',true)}</select></label>${Flow.field('入库单UUID（可选）','receipt_id')}${Flow.field('标签宽度（毫米）','width_mm','number','60','min="40" max="100" required')}${Flow.field('标签高度（毫米）','height_mm','number','50','min="40" max="100" required')}`,async b=>{const ids=b.numbers.trim().split(/[\s,，]+/).filter(Boolean);const body={width_mm:Number(b.width_mm),height_mm:Number(b.height_mm)};if(ids.length)body.bundle_ids=ids;if(b.batch_id)body.batch_id=b.batch_id;if(b.receipt_id)body.receipt_id=b.receipt_id;const d=await API.request('/labels/jobs',{method:'POST',body});const a=document.createElement('a');a.href='/labels/preview/'+d.id;a.target='_blank';a.rel='noopener';a.className='button primary';a.textContent='打开打印预览 / Print preview';Business.open('标签预览',`<p>已生成${d.count}个授权标签。预览、打印请求及重复打印均留痕。</p><div id="label-preview-link"></div>`);$('label-preview-link').append(a);});}};
const labelsMenu=Business.menu.bind(Business);Business.menu=function(){labelsMenu();const b=document.createElement('button');b.className='button secondary';b.textContent='捆包二维码';b.disabled=!Business.can('label:print');b.onclick=()=>Labels.form().catch(e=>notify(e.message));document.querySelector('.business-menu').append(b);};
